# Fails if the list of files on standard input (a directory listing or the contents of a zip, deb, rpm, pkg.tar.zst or pkg)
# is missing the HTML help. Usage: <command listing files> | check-help.sh <name>
set -u
name="${1:-bundle}"
listing="$(cat)"
status=0
for file in help/index.html help/commands/index.htm help/language/index.html; do
	if grep -Eq "(^|/)${file//./\\.}\$" <<<"$listing"; then
		echo "ok       $name: $file"
	else
		echo "MISSING  $name: $file" >&2
		status=1
	fi
done
exit $status
